import { expect, expectStatus, test, type Extraction, type Vendor } from "../../fixtures";

test("rejecting one document sends the whole vendor back", { tag: "@LIF-02" }, async ({ factory, apiAs }) => {
  // Arrange: a vendor submitted for review with three pending extractions.
  const { vendor, documents, extractions } = await factory.vendorInReview();
  const reviewer = await apiAs("reviewer");
  const member = await apiAs("member");

  // Act: the reviewer rejects the contract extraction with a note.
  const decision = await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
    data: { decision: "reject", note: "Wrong counterparty" },
  });

  // Assert: the decision response reports the rejection.
  const returned = await expectStatus<Extraction>(decision, 200);
  expect(returned.status).toBe("rejected");
  expect(returned.review_note).toBe("Wrong counterparty");

  // Assert: the stored extraction and vendor reflect the rejection.
  const stored = await factory.extraction(documents.contract.id, "reviewer");
  expect(stored.status).toBe("rejected");
  expect(stored.review_note).toBe("Wrong counterparty");

  const current = await expectStatus<Vendor>(await member.get(`/api/vendors/${vendor.id}`), 200);
  expect(current.status).toBe("rejected");

  // Assert: the audit trail records extraction.rejected, then vendor.rejected.
  const trail = await expectStatus<{ items: { action: string }[] }>(
    await member.get(`/api/vendors/${vendor.id}/audit`),
    200,
  );
  const actions = trail.items
    .map((event) => event.action)
    .filter((action) => action === "extraction.rejected" || action === "vendor.rejected");
  expect(actions).toEqual(["extraction.rejected", "vendor.rejected"]);
});
